local $/; my $f = shift; open my $i, '<:raw', $f; my $t = <$i>; close $i;
my $old = "# this image's .bss, as one region\n    leaq .Lws_fdt(%rip), %rcx\n    leaq 48(%rsp), %rdx\n    movq \$48, %r8\n    call VirtualQuery\n    movq .Lws_fk_proc(%rip), %rcx\n    movq 48(%rsp), %rdx\n    movq 48(%rsp), %r8\n    movq 72(%rsp), %r9\n    movq \$0, 32(%rsp)\n    call WriteProcessMemory\n    testq %rax, %rax\n    jz .Lws_fr_abort\n";
my $new = "# every writable region of this image (.bss: the runtime's and the layer's data)\n    movq \$4194304, %rsi\n.Lws_fr_img:\n    movq %rsi, %rcx\n    leaq 48(%rsp), %rdx\n    movq \$48, %r8\n    call VirtualQuery\n    testq %rax, %rax\n    jz .Lws_fr_img_done\n    cmpq \$4194304, 56(%rsp)\n    jne .Lws_fr_img_done\n    movq 84(%rsp), %rax\n    shlq \$32, %rax\n    shrq \$32, %rax\n    cmpq \$4, %rax\n    jne .Lws_fr_img_next\n    movq .Lws_fk_proc(%rip), %rcx\n    movq 48(%rsp), %rdx\n    movq 48(%rsp), %r8\n    movq 72(%rsp), %r9\n    movq \$0, 32(%rsp)\n    call WriteProcessMemory\n    testq %rax, %rax\n    jz .Lws_fr_abort\n.Lws_fr_img_next:\n    movq 48(%rsp), %rsi\n    addq 72(%rsp), %rsi\n    jmp .Lws_fr_img\n.Lws_fr_img_done:\n";
my $k = index($t, $old); die "nf" if $k < 0; substr($t, $k, length($old)) = $new;
open my $o, '>:raw', $f; print $o $t; close $o; print "ok\n";
